def _ordinary_claim_power_risk_context(
    snapshot: dict[str, object] | None, declaration: dict[str, object],
    assessment: dict[str, object], candidate: dict[str, object],
    campaign_root: dict[str, object], rows: list[dict[str, object]],
) -> dict[str, object] | None:
    """Keep estimated native-power risk within the existing own county claim."""
    if (
        not isinstance(snapshot, dict)
        or candidate.get("rule_id") not in {
            _CONSERVATIVE_FEUDAL_PLAYER_CLAIM_WAR_ENTRY["rule_id"],
            "general-native-war-entry-battle-prior-v1",
        }
    ):
        return None
    played = snapshot.get("played_character")
    own_claims = _player_claim_declarations(
        [declaration], actor_character_id=played.get("character_id") if isinstance(played, dict) else None,
    )
    if not _adjacent_independent_county_player_claims(own_claims, campaign_root):
        return None
    faction_alert = _same_frame_player_faction_alerts(rows, snapshot)
    faction_context = _general_war_entry_faction_context(campaign_root, faction_alert)
    target = declaration.get("target_character_id")
    for row in reversed(rows):
        source = _effective_command_result(row)
        if (
            row.get("ok") is True and isinstance(source, dict)
            and source.get("step") == f"query-war-entry-assessments-v1-1-{target}"
            and source.get("queried_snapshot_id") == snapshot.get("snapshot_id")
            and source.get("queried_revision") == snapshot.get("revision")
            and source.get("queried_native_revision") == snapshot.get("native_revision")
        ):
            return {"policy": _CONSERVATIVE_FEUDAL_PLAYER_CLAIM_WAR_ENTRY["rule_id"],
                    "selection_policy": candidate["rule_id"], "campaign_root": campaign_root,
                    "assessment": assessment, "assessment_source": source,
                    "faction_alert": faction_alert, "faction_context": faction_context}
    return None

force_admission = assess_ordinary_prewar_force_admission_v2(
